#include <vector>
#include <algorithm>
using namespace std;

class Solution {
public:
    int minDifference(vector<int>& nums) {
        if (nums.size() <= 4) return 0;

        sort(nums.begin(), nums.end());

        int result = INT_MAX;
        for (int i = 0; i < 4; ++i) {
            result = min(result, nums[nums.size() - 4 + i] - nums[i]);
        }

        return result;
    }
};
